mapper.select:
select t.acs_id,t.acs_id acsId,t.machine_id,t.machine_id machineId,t.status_cd,t.status_cd
statusCd,t.community_id,t.community_id communityId,t.location_id,t.location_id locationId,
t.location_name,t.location_name locationName,t.create_time createTime,
ac.machine_code machineCode,ac.machine_name machineName
from access_control_shop t
left join access_control ac on ac.machine_id = t.machine_id and ac.status_cd = '0'
where 1 =1

    and t.acs_id= #{acsId}


    and t.machine_id= #{machineId}


    and t.location_id= #{locationId}


    and t.location_name= #{locationName}


    and ac.machine_name like concat('%', #{machineName}, '%')


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update access_control_shop t set t.status_cd = #{statusCd}

    , t.machine_id= #{machineId}


    , t.location_id= #{locationId}


    , t.location_name= #{locationName}

where 1=1

    and t.acs_id= #{acsId}


    and t.community_id= #{communityId}

